const depthWordmark=document.querySelector('[data-depth-wordmark]');
if(depthWordmark&&matchMedia('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)').matches){
  let frame=0;
  depthWordmark.addEventListener('pointermove',event=>{
    if(frame)cancelAnimationFrame(frame);
    frame=requestAnimationFrame(()=>{
      const rect=depthWordmark.getBoundingClientRect();
      const x=(event.clientX-rect.left)/rect.width-.5;
      const y=(event.clientY-rect.top)/rect.height-.5;
      depthWordmark.style.setProperty('--depth-tilt-x',`${(-y*9).toFixed(2)}deg`);
      depthWordmark.style.setProperty('--depth-tilt-y',`${(x*12).toFixed(2)}deg`);
      frame=0;
    });
  },{passive:true});
  depthWordmark.addEventListener('pointerleave',()=>{
    if(frame)cancelAnimationFrame(frame);
    frame=0;
    depthWordmark.style.removeProperty('--depth-tilt-x');
    depthWordmark.style.removeProperty('--depth-tilt-y');
  });
}
const heroGlass=document.getElementById('hero-glass');
if(heroGlass&&matchMedia('(min-width: 761px) and (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)').matches){
  let frame=0;
  let pointer=null;
  const positionGlass=()=>{
    frame=0;
    if(!pointer)return;
    const rect=heroGlass.getBoundingClientRect();
    const radius=Math.min(95,rect.width*.2);
    const x=Math.max(radius,Math.min(rect.width-radius,pointer.x-rect.left));
    const y=Math.max(radius,Math.min(rect.height-radius,pointer.y-rect.top));
    heroGlass.style.setProperty('--lens-x',`${x}px`);
    heroGlass.style.setProperty('--lens-y',`${y}px`);
    heroGlass.style.setProperty('--art-x',`${((x/rect.width)-.5)*18}px`);
    heroGlass.style.setProperty('--art-y',`${((y/rect.height)-.5)*12}px`);
    heroGlass.style.setProperty('--art-rotate',`${((x/rect.width)-.5)*1.8}deg`);
  };
  heroGlass.addEventListener('pointermove',event=>{
    pointer={x:event.clientX,y:event.clientY};
    heroGlass.classList.add('is-engaged');
    if(!frame)frame=requestAnimationFrame(positionGlass);
  },{passive:true});
  heroGlass.addEventListener('pointerleave',()=>{
    pointer=null;
    if(frame)cancelAnimationFrame(frame);
    frame=0;
    heroGlass.classList.remove('is-engaged');
    ['--lens-x','--lens-y','--art-x','--art-y','--art-rotate'].forEach(property=>heroGlass.style.removeProperty(property));
  });
}
