const activeProduct = /^\/demos\/tienda-ropa\/producto\/\d+$/.test(path) ? products.find(product=>product.id===Number(path.split('/').pop())) : null;
const description = descriptions[path] || (activeProduct ? `${activeProduct.name} de NORTHLINE. Producto ficticio de demostración; no se realizan ventas.` : legalRoutes[path] ? `Borrador de ${legal[legalRoutes[path]].title} de ${studio.name}.` : `${studio.name}: contenido de demostración.`);
document.querySelector('meta[name="description"]').content=description;
for(const [key,value] of Object.entries(studio.colors)){document.documentElement.style.setProperty(`--vyro-${key.replace(/[A-Z]/g,letter=>`-${letter.toLowerCase()}`)}`,value);}
for (const [property, content] of [['og:type','website'],['og:locale','es_CR'],['og:title',document.title],['og:description',description],['og:site_name',studio.fullName],['og:image',studio.assets.socialImage]]) {
  const meta=document.createElement('meta'); meta.setAttribute('property',property); meta.content=content; document.head.append(meta);
}
if (path.startsWith('/demos/') || legalRoutes[path] || path === '/admin' || path === '/retirar-consentimiento') { const meta=document.createElement('meta'); meta.name='robots'; meta.content='noindex,nofollow'; document.head.append(meta); }

document.querySelectorAll('.menu-toggle').forEach(toggle=>toggle.addEventListener('click',()=>{ const nav=document.getElementById(toggle.getAttribute('aria-controls')); const open=toggle.getAttribute('aria-expanded')!=='true'; toggle.setAttribute('aria-expanded',String(open)); nav.classList.toggle('open',open); }));
document.querySelectorAll('nav a').forEach(link=>link.addEventListener('click',()=>{ document.querySelectorAll('.menu-toggle').forEach(toggle=>toggle.setAttribute('aria-expanded','false')); document.querySelectorAll('nav.open').forEach(nav=>nav.classList.remove('open')); }));
document.querySelectorAll('input[type="date"]').forEach(input=>input.min=new Date().toISOString().slice(0,10));
document.querySelectorAll('.demo-booking').forEach(form=>form.addEventListener('submit',event=>{ event.preventDefault(); const message=form.querySelector('.form-message'); if(!form.reportValidity()) return; const date=new FormData(form).get('date'); if(date<new Date().toISOString().slice(0,10)){message.textContent='Elegí una fecha futura.';return;} message.textContent='Simulación completada. No se creó ninguna reserva o cita real ni se guardaron datos.'; form.reset(); }));
document.querySelectorAll('[data-service-select]').forEach(link=>link.addEventListener('click',()=>{const select=document.querySelector('[name="service"]'); if(select) select.value=link.dataset.serviceSelect;}));
document.querySelectorAll('[data-food-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-food-filter]').forEach(b=>b.classList.toggle('active',b===button)); renderFood(button.dataset.foodFilter);}));
function renderFood(filter='todos') { const grid=document.getElementById('food-grid'); if(!grid)return; grid.innerHTML=food.map(([name,category,price,description],i)=>({name,category,price,description,i})).filter(item=>filter==='todos'||item.category===filter).map(({name,category,price,description,i})=>`<article class="food-card">${img(`food-${String(i+1).padStart(2,'0')}.jpg`,name)}<div><span>${category}</span><h3>${name}</h3><p>${description}</p><strong>${money(price)}</strong></div></article>`).join(''); }
renderFood();
const quoteForm=document.getElementById('quote-form');
if(quoteForm) quoteForm.elements.contactType.addEventListener('change',()=>{const input=quoteForm.elements.contact;const email=quoteForm.elements.contactType.value==='correo';input.type=email?'email':'tel';input.inputMode=email?'email':'tel';input.autocomplete=email?'email':'tel';input.placeholder=email?'nombre@ejemplo.com':'+506 0000 0000';input.value='';});
if(quoteForm) quoteForm.addEventListener('submit',async event=>{event.preventDefault();const message=document.getElementById('quote-message');const data=Object.fromEntries(new FormData(quoteForm)); const body={...data,privacy:quoteForm.elements.privacy.checked,terms:quoteForm.elements.terms.checked}; if(!quoteForm.reportValidity()){message.textContent='Completá los campos señalados y autorizá el uso de datos para responderte.';return;} message.textContent='Enviando solicitud…'; try{const response=await fetch('/api/contact',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok){message.textContent=result.error||'No se pudo enviar la solicitud.';return;}message.innerHTML=`Solicitud recibida en este servidor. Guardá tu identificador <code>${esc(result.requestId)}</code> y código de retirada <code>${esc(result.withdrawalToken)}</code>. No se envió correo automático. También podés <a href="${wa('Hola, envié una solicitud de cotización desde ${studio.fullName}.')}" target="_blank" rel="noopener noreferrer">confirmar el contacto por WhatsApp</a>.`;quoteForm.reset();}catch{message.textContent='No se pudo conectar con el servidor. Intentá de nuevo o contactanos por WhatsApp.';}});
const withdrawForm=document.getElementById('withdraw-form');
if(withdrawForm) withdrawForm.addEventListener('submit',async event=>{event.preventDefault();const message=withdrawForm.querySelector('.form-message');try{const response=await fetch('/api/consent/withdraw',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(withdrawForm)))});const result=await response.json();message.textContent=result.message||result.error;}catch{message.textContent='No se pudo conectar con el servidor.';}});
function renderProducts(){const grid=document.getElementById('product-grid');if(!grid)return;const category=document.getElementById('category-filter').value,price=Number(document.getElementById('price-filter').value),size=document.getElementById('size-filter').value,sort=document.getElementById('sort-filter').value;const items=products.filter(p=>(!category||p.category===category)&&(!price||p.price<=price)&&(!size||p.sizes.includes(size)));items.sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:sort==='name'?a.name.localeCompare(b.name):a.id-b.id);grid.innerHTML=items.length?items.map(productCard).join(''):'<p class="empty-state">No hay piezas con esos filtros. Probá otra combinación.</p>';document.getElementById('result-count').textContent=`${items.length} ${items.length===1?'pieza':'piezas'}`;}
['category-filter','price-filter','size-filter','sort-filter'].forEach(id=>document.getElementById(id)?.addEventListener('change',renderProducts));document.getElementById('filters-reset')?.addEventListener('click',()=>{['category-filter','price-filter','size-filter','sort-filter'].forEach(id=>document.getElementById(id).selectedIndex=0);renderProducts();});renderProducts();
const mainImage=document.getElementById('product-main-image');
if(mainImage){const zoomImage=document.getElementById('product-zoom-image'),zoom=document.getElementById('product-zoom');document.querySelectorAll('[data-gallery-source]').forEach(button=>button.addEventListener('click',()=>{mainImage.src=button.dataset.gallerySource;mainImage.alt=button.dataset.galleryAlt;zoomImage.src=button.dataset.gallerySource;zoomImage.alt=button.dataset.galleryAlt;document.querySelectorAll('[data-gallery-source]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));}));document.getElementById('product-zoom-open').addEventListener('click',()=>zoom.showModal());document.getElementById('product-zoom-close').addEventListener('click',()=>zoom.close());zoom.addEventListener('click',event=>{if(event.target===zoom)zoom.close();});}
const addForm=document.getElementById('add-cart-form'); if(addForm)addForm.addEventListener('submit',event=>{event.preventDefault();if(!addForm.reportValidity())return;const product=products.find(p=>p.id===Number(addForm.dataset.productId));const data=new FormData(addForm),size=data.get('size'),color=data.get('color'),qty=Number(data.get('quantity'));if(!product.sizes.includes(size)||!product.colors.includes(color)||!Number.isInteger(qty)||qty<1||qty>10)return;const cart=getCart(),existing=cart.find(item=>item.id===product.id&&item.size===size&&item.color===color);if(existing)existing.qty=Math.min(10,existing.qty+qty);else cart.push({id:product.id,size,color,qty});setCart(cart);addForm.querySelector('.form-message').textContent='Producto agregado a la bolsa de demostración.';openCart();});
function renderCart(){const list=document.getElementById('cart-items');if(!list)return;const cart=getCart();list.innerHTML=cart.length?cart.map((item,index)=>{const product=products.find(p=>p.id===item.id);return `<article class="cart-item">${img(product.image,product.name)}<div><h3>${product.name}</h3><p>${item.size} · ${item.color}</p><strong>${money(product.price*item.qty)}</strong><label>Cantidad <input data-cart-qty="${index}" type="number" min="1" max="10" value="${item.qty}"></label><button data-cart-remove="${index}" type="button">Eliminar</button></div></article>`;}).join(''):'<p class="empty-state">Tu bolsa está vacía. Explorá la colección.</p>';const total=cart.reduce((sum,item)=>sum+(products.find(p=>p.id===item.id)?.price||0)*item.qty,0);document.getElementById('cart-subtotal').textContent=money(total);document.getElementById('cart-total').textContent=money(total);list.querySelectorAll('[data-cart-qty]').forEach(input=>input.addEventListener('change',()=>{const cart=getCart(),qty=Number(input.value);if(!Number.isInteger(qty)||qty<1||qty>10){input.value=cart[Number(input.dataset.cartQty)].qty;return;}cart[Number(input.dataset.cartQty)].qty=qty;setCart(cart);renderCart();}));list.querySelectorAll('[data-cart-remove]').forEach(button=>button.addEventListener('click',()=>{const cart=getCart();cart.splice(Number(button.dataset.cartRemove),1);setCart(cart);renderCart();}));}
function openCart(){const drawer=document.getElementById('cart-drawer');if(!drawer)return;renderCart();drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');document.getElementById('cart-backdrop').hidden=false;document.getElementById('cart-close').focus();}
function closeCart(){const drawer=document.getElementById('cart-drawer');if(!drawer)return;drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');document.getElementById('cart-backdrop').hidden=true;document.getElementById('cart-open')?.focus();}
document.getElementById('cart-open')?.addEventListener('click',openCart);document.getElementById('cart-close')?.addEventListener('click',closeCart);document.getElementById('cart-backdrop')?.addEventListener('click',closeCart);document.getElementById('cart-clear')?.addEventListener('click',()=>{setCart([]);renderCart();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.getElementById('cart-drawer')?.classList.contains('open'))closeCart();});updateCartCount();
const summary=document.getElementById('checkout-summary');if(summary){const cart=getCart();const total=cart.reduce((sum,item)=>sum+(products.find(p=>p.id===item.id)?.price||0)*item.qty,0);summary.innerHTML=`<h2>Resumen de muestra</h2>${cart.map(item=>{const p=products.find(product=>product.id===item.id);return `<div><span>${p.name} · ${item.size} × ${item.qty}</span><strong>${money(p.price*item.qty)}</strong></div>`;}).join('')}<div class="checkout-total"><span>Total ficticio</span><strong>${money(total)}</strong></div>`;document.getElementById('checkout-finish').disabled=cart.length===0;}
document.getElementById('checkout-finish')?.addEventListener('click',()=>{document.getElementById('checkout-message').textContent='Simulación terminada. No se procesó un pago ni se creó un pedido.';setCart([]);document.getElementById('checkout-finish').disabled=true;});
const adminLogin=document.getElementById('admin-login');if(adminLogin)adminLogin.addEventListener('submit',async event=>{event.preventDefault();const message=adminLogin.querySelector('.form-message');try{const response=await fetch('/api/admin/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(adminLogin)))});const result=await response.json();if(!response.ok){message.textContent=result.error;return;}adminLogin.hidden=true;document.getElementById('admin-panel').hidden=false;await loadAdmin();}catch{message.textContent='No se pudo acceder al servidor.';}});
async function loadAdmin(){const response=await fetch('/api/admin/requests');if(!response.ok)return;const data=await response.json();document.getElementById('admin-records').innerHTML=`<h2>Solicitudes (${data.requests.length})</h2>${data.requests.map(request=>`<article class="admin-record"><h3>${esc(request.name)} · ${esc(request.project_type)}</h3><p>${esc(request.contact_type)}: ${esc(request.contact)}</p><p>${esc(request.description)}</p><small>${esc(request.created_at)} · ${esc(request.status)} · ${esc(request.id)}</small><details><summary>Eventos de consentimiento</summary>${data.consents.filter(c=>c.request_id===request.id).map(c=>`<p>${esc(c.consent_type)} · ${esc(c.state)} · versión ${esc(c.document_version)} · ${esc(c.created_at)}</p>`).join('')}</details></article>`).join('')}`;}
document.getElementById('admin-logout')?.addEventListener('click',async()=>{await fetch('/api/admin/logout',{method:'POST'});location.reload();});
